import time
from functools import wraps

def retry(times: int = 3, delay: float = 0.5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except ConnectionError as error:
                    last_error = error
                    time.sleep(delay)
            raise last_error
        return wrapper
    return decorator

@retry(times=3)
def charge_gateway(order_id: str) -> dict:
    return payment_client.charge(order_id)
